{"optimized_code": "app.get('/api/users', async (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const limit = 50;
  const skip = (page - 1) * limit;

  const users = await db.collection('users').find({}).skip(skip).limit(limit).toArray();
  const userIds = users.map(u => u._id);

  const [profiles, posts] = await Promise.all([
    db.collection('profiles').find({ userId: { $in: userIds } }).toArray(),
    db.collection('posts').find({ userId: { $in: userIds } }).toArray()
  ]);

  const profileMap = new Map(profiles.map(p => [p.userId, p]));
  const postMap = posts.reduce((acc, post) => {
    acc[post.userId] = acc[post.userId] || [];
    acc[post.userId].push(post);
    return acc;
  }, {});

  const enrichedUsers = users.map(user => ({
    ...user,
    profile: profileMap.get(user._id),
    posts: postMap[user._id] || []
  }));

  res.json(enrichedUsers);
});", "improvements": ["Added pagination (50 per page)", "Batch queries using $in operator", "Parallel execution with Promise.all", "In-memory mapping instead of nested loops"]}
